-- 锐途就业数据库初始化脚本-- 包含建库、建表语句和基础数据

-- 创建数据库
CREATE DATABASE IF NOT EXISTS `shanxiligong_employment_db` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `shanxiligong_employment_db`;


SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- 用户表
DROP TABLE IF EXISTS `shanxiligong_sys_user`;
CREATE TABLE `shanxiligong_sys_user` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `username` VARCHAR(50) NOT NULL COMMENT '用户名',
  `password` VARCHAR(100) NOT NULL COMMENT '密码',
  `nickname` VARCHAR(50) DEFAULT NULL COMMENT '昵称',
  `email` VARCHAR(100) DEFAULT NULL COMMENT '邮箱',
  `phone` VARCHAR(20) DEFAULT NULL COMMENT '手机号',
  `avatar` VARCHAR(255) DEFAULT NULL COMMENT '头像地址',
  `role` TINYINT NOT NULL DEFAULT 0 COMMENT '0普通用户 1管理员',
  `status` TINYINT NOT NULL DEFAULT 1 COMMENT '0禁用 1正常',
  `last_login_time` DATETIME DEFAULT NULL COMMENT '最后登录时间',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_username` (`username`),
  KEY `idx_username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户表';

-- REGION_SCHEMA_START
-- 地区字典
DROP TABLE IF EXISTS `shanxiligong_dict_region`;
CREATE TABLE `shanxiligong_dict_region` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` VARCHAR(100) NOT NULL COMMENT '地区名',
  `parent_id` BIGINT DEFAULT 0 COMMENT '上级ID，0为省级根节点',
  `code` VARCHAR(12) DEFAULT NULL COMMENT '行政区划编码',
  `level` TINYINT NOT NULL DEFAULT 0 COMMENT '层级：0省级 1市级 2区县级 3乡镇级',
  `sort_order` INT DEFAULT 0 COMMENT '排序',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_code` (`code`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_parent_level` (`parent_id`, `level`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='地区字典';
-- REGION_SCHEMA_END

-- 行业字典
DROP TABLE IF EXISTS `shanxiligong_dict_industry`;
CREATE TABLE `shanxiligong_dict_industry` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` VARCHAR(50) NOT NULL COMMENT '行业名',
  `sort_order` INT DEFAULT 0 COMMENT '排序',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='行业字典';

-- 专业字典
DROP TABLE IF EXISTS `shanxiligong_dict_major`;
CREATE TABLE `shanxiligong_dict_major` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` VARCHAR(50) NOT NULL COMMENT '专业名',
  `sort_order` INT DEFAULT 0 COMMENT '排序',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='专业字典';

-- 就业数据表
DROP TABLE IF EXISTS `shanxiligong_employment_data`;
CREATE TABLE `shanxiligong_employment_data` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `region_id` BIGINT NOT NULL COMMENT '城市ID',
  `province_id` BIGINT NOT NULL COMMENT '省份ID',
  `industry_id` BIGINT NOT NULL COMMENT '行业ID',
  `major_id` BIGINT NOT NULL COMMENT '专业ID',
  `education` VARCHAR(10) NOT NULL COMMENT '学历：专科/本科/硕士/博士',
  `year` INT NOT NULL COMMENT '年份',
  `avg_salary` DECIMAL(10,2) DEFAULT NULL COMMENT '平均月薪',
  `median_salary` DECIMAL(10,2) DEFAULT NULL COMMENT '薪资中位数',
  `employment_rate` DECIMAL(5,2) DEFAULT NULL COMMENT '就业率',
  `sample_size` INT DEFAULT NULL COMMENT '样本量',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dimension` (`region_id`, `industry_id`, `major_id`, `education`, `year`),
  KEY `idx_province` (`province_id`),
  KEY `idx_year` (`year`),
  KEY `idx_education` (`education`),
  KEY `idx_industry` (`industry_id`),
  KEY `idx_major` (`major_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='就业数据';

-- 收藏表
DROP TABLE IF EXISTS `shanxiligong_user_favorite`;
CREATE TABLE `shanxiligong_user_favorite` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT NOT NULL COMMENT '用户ID',
  `data_id` BIGINT NOT NULL COMMENT '数据ID',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_data` (`user_id`, `data_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='收藏表';

-- 公告表
DROP TABLE IF EXISTS `shanxiligong_announcement`;
CREATE TABLE `shanxiligong_announcement` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` VARCHAR(200) NOT NULL COMMENT '标题',
  `summary` VARCHAR(500) DEFAULT NULL COMMENT '摘要',
  `content` TEXT NOT NULL COMMENT '正文',
  `status` TINYINT NOT NULL DEFAULT 1 COMMENT '0下架 1上架',
  `publisher_id` BIGINT NOT NULL COMMENT '发布人ID',
  `publish_time` DATETIME DEFAULT NULL COMMENT '发布时间',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` DATETIME DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`, `deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='公告表';

-- 反馈表
DROP TABLE IF EXISTS `shanxiligong_feedback`;
CREATE TABLE `shanxiligong_feedback` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT NOT NULL COMMENT '用户ID',
  `title` VARCHAR(200) NOT NULL COMMENT '标题',
  `content` TEXT NOT NULL COMMENT '内容',
  `type` VARCHAR(20) NOT NULL COMMENT '类型',
  `status` TINYINT NOT NULL DEFAULT 0 COMMENT '0待处理 1已处理',
  `reply_content` TEXT DEFAULT NULL COMMENT '回复内容',
  `reply_user_id` BIGINT DEFAULT NULL COMMENT '回复人ID',
  `reply_time` DATETIME DEFAULT NULL COMMENT '回复时间',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `deleted` TINYINT NOT NULL DEFAULT 0 COMMENT '0正常 1删除',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_type_status` (`type`, `status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='反馈表';

-- 操作日志
DROP TABLE IF EXISTS `shanxiligong_operation_log`;
CREATE TABLE `shanxiligong_operation_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `operator_id` BIGINT NOT NULL COMMENT '操作人ID',
  `operator_name` VARCHAR(50) NOT NULL COMMENT '操作人',
  `operation_type` VARCHAR(50) NOT NULL COMMENT '操作类型',
  `operation_target` VARCHAR(200) DEFAULT NULL COMMENT '操作对象',
  `operation_detail` TEXT DEFAULT NULL COMMENT '详情',
  `ip_address` VARCHAR(50) DEFAULT NULL COMMENT 'IP',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_operator` (`operator_id`),
  KEY `idx_type` (`operation_type`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='操作日志';

-- 查询日志
DROP TABLE IF EXISTS `shanxiligong_query_log`;
CREATE TABLE `shanxiligong_query_log` (
  `id` BIGINT NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` BIGINT DEFAULT NULL COMMENT '用户ID',
  `query_type` VARCHAR(50) NOT NULL COMMENT '查询类型',
  `query_params` VARCHAR(500) DEFAULT NULL COMMENT '查询参数',
  `create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '查询时间',
  PRIMARY KEY (`id`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_query_type` (`query_type`, `create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='查询日志';

SET FOREIGN_KEY_CHECKS = 1;


